import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import NavTop from '../components/NavTop';
import Footer from '../components/Footer';

const CheckoutPage = () => {
  const [processing, setProcessing] = useState(false);
  const [success, setSuccess] = useState(false);
  const navigate = useNavigate();

  const handlePay = (e) => {
    e.preventDefault();
    setProcessing(true);
    setTimeout(() => {
      setProcessing(false);
      setSuccess(true);
      setTimeout(() => navigate('/tenant'), 3000);
    }, 2000);
  };

  return (
    <div className="pt-20">
      <NavTop role="tenant" />
      <main className="pt-12 pb-20 px-margin-mobile md:px-margin-desktop max-w-container-max mx-auto">
        <h1 className="text-4xl font-bold mb-10">Confirm and pay</h1>
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-gutter items-start">
          <div className="lg:col-span-5 glass-card rounded-xl p-6 shadow-sm">
            <div className="flex gap-4 mb-6">
              <div className="w-32 h-24 rounded-lg overflow-hidden shrink-0"><img src="https://lh3.googleusercontent.com/aida-public/AB6AXuDk3DCzk20qNAz3_5BL5cMADTFz1G3jbCzTcaPghORJsegPq_tlTZW1Ruzh8nGSAD7Q4MtfWKju6icIDIBaBw8_hKYX5RXWPwKSL4_j80hlt29jLFhzNPIXAarXLal3pqEwx9I7ygkTFezRlaNcPCPLtB-V7q2sM2zJVpWvCYrJZczWftg5gqNEqAvhz3EgnmMdEE9tJxVgGrhaFnB1XxIWjTtk0KVi5V9jV5W-h7dw5CycwoeHrVUmmSSz2iJ6CpNX2JUIru9EFbc" className="w-full h-full object-cover" alt="Property"/></div>
              <div className="flex flex-col justify-center">
                <p className="text-xs text-primary font-bold uppercase tracking-wider">Entire Villa</p>
                <h2 className="font-bold text-xl">Azure Heights Villa</h2>
                <div className="flex items-center gap-1 text-sm"><span className="material-symbols-outlined text-sm" style={{fontVariationSettings: "'FILL' 1"}}>star</span> 4.98 <span className="text-secondary">(124 reviews)</span></div>
              </div>
            </div>
            <div className="border-t border-outline-variant pt-6 space-y-4">
              <h3 className="font-bold text-lg">Price details</h3>
              <div className="flex justify-between"><span>$850.00 x 5 nights</span><span>$4,250.00</span></div>
              <div className="flex justify-between font-bold text-xl pt-4 border-t border-outline-variant"><span>Total (USD)</span><span>$4,477.50</span></div>
            </div>
          </div>
          <div className="lg:col-span-7 glass-panel rounded-xl p-8 shadow-sm">
            <h2 className="text-2xl font-bold mb-8">Payment method</h2>
            <form onSubmit={handlePay} className="space-y-6">
              <div className="space-y-2">
                <label className="text-sm font-bold text-secondary uppercase">Card Information</label>
                <div className="relative">
                  <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-secondary">credit_card</span>
                  <input className="w-full pl-12 pr-4 py-4 bg-white border border-outline-variant rounded-lg focus:ring-2 focus:ring-primary" placeholder="Card number" defaultValue="4242 4242 4242 4242" />
                </div>
                <div className="grid grid-cols-2 gap-4 mt-4">
                  <input className="w-full px-4 py-4 bg-white border border-outline-variant rounded-lg" placeholder="MM / YY" />
                  <input className="w-full px-4 py-4 bg-white border border-outline-variant rounded-lg" placeholder="CVV" />
                </div>
              </div>
              <button disabled={processing} className={`w-full py-5 rounded-full font-bold text-lg transition-all shadow-lg flex items-center justify-center gap-3 ${success ? 'bg-emerald-600 text-white' : 'bg-primary text-white hover-scale active-scale'}`}>
                {processing ? <span className="material-symbols-outlined animate-spin">progress_activity</span> : success ? "Payment Confirmed" : "Confirm & Pay"}
                {!processing && !success && <span className="material-symbols-outlined">lock</span>}
              </button>
            </form>
          </div>
        </div>
      </main>
      <div className={`success-toast fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] ${success ? 'active' : 'opacity-0'}`}>
        <div className="glass-card bg-emerald-50/90 border-emerald-200 px-8 py-4 rounded-full shadow-xl flex items-center gap-4 border-2">
          <div className="w-8 h-8 rounded-full bg-emerald-500 flex items-center justify-center text-white"><span className="material-symbols-outlined">check</span></div>
          <div><p className="font-bold text-emerald-900">Success! Deposit Secured</p><p className="text-xs text-emerald-700">A confirmation email has been sent to your inbox.</p></div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default CheckoutPage;
